def choose_move(observation):
    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def to_pair(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return [int(v[0]), int(v[1])]
        return None

    def norm_pos(v):
        p = to_pair(v)
        if p is not None:
            return p
        if isinstance(v, dict):
            for a, b in (("x", "y"), ("row", "col"), ("r", "c")):
                if a in v and b in v and is_num(v.get(a)) and is_num(v.get(b)):
                    return [int(v.get(a)), int(v.get(b))]
        return None

    def get_positions(obj):
        out = []
        if obj is None:
            return out
        if isinstance(obj, dict):
            for k in ("positions", "cells", "targets", "items", "agents", "players", "enemies", "resources", "goals", "bases", "flags", "territories"):
                if k in obj:
                    out.extend(get_positions(obj.get(k)))
            p = norm_pos(obj)
            if p is not None:
                out.append(p)
            return out
        if isinstance(obj, (list, tuple)):
            for it in obj:
                p = norm_pos(it)
                if p is not None:
                    out.append(p)
                elif isinstance(it, (list, tuple, dict)):
                    out.extend(get_positions(it))
            return out
        p = norm_pos(obj)
        if p is not None:
            out.append(p)
        return out

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_step(d):
        return -1 if d < 0 else (1 if d > 0 else 0)

    def sign_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def neighbors(pos):
        return [[pos[0] + 1, pos[1]], [pos[0] - 1, pos[1]], [pos[0], pos[1] + 1], [pos[0], pos[1] - 1]]

    # Find self position
    me = None
    for key in ("self", "agent", "player", "unit", "position", "pos", "loc", "location"):
        if key in observation:
            me = norm_pos(observation.get(key))
            if me is not None:
                break
    if me is None:
        for key in ("my_position", "agent_position", "player_position"):
            if key in observation:
                me = norm_pos(observation.get(key))
                if me is not None:
                    break
    if me is None:
        me = [0, 0]

    # Grid / bounds
    grid = observation.get("grid")
    h = w = None
    walls = set()
    if isinstance(grid, (list, tuple)) and grid:
        h = len(grid)
        if isinstance(grid[0], (list, tuple)):
            w = len(grid[0])
            for y, row in enumerate(grid):
                if isinstance(row, (list, tuple)):
                    for x, cell in enumerate(row):
                        if cell in (1, "#", "wall", "W", True):
                            walls.add((x, y))
        else:
            w = len(grid)

    # Extract candidates
    resources = []
    for k in ("resources", "resource_positions", "resource", "items", "collectibles", "food", "coins"):
        resources.extend(get_positions(observation.get(k)))
    targets = []
    for k in ("targets", "goals", "goal", "objectives", "capture_points", "territory_targets", "bases", "flag", "flags"):
        targets.extend(get_positions(observation.get(k)))
    threats = []
    for k in ("enemies", "enemy", "opponents", "opponent", "ghosts", "chasers", "predators"):
        threats.extend(get_positions(observation.get(k)))

    # Also infer from agent lists
    agents = get_positions(observation.get("agents")) + get_positions(observation.get("players"))
    for p in agents:
        if p != me:
            threats.append(p)

    # Remove duplicates
    def dedup(points):
        seen = set()
        out = []
        for p in points:
            t = (p[0], p[1])
            if t not in seen:
                seen.add(t)
                out.append(p)
        return out

    resources = dedup(resources)
    targets = dedup(targets)
    threats = dedup(threats)

    # Candidate moves
    moves = [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]
    best_move = [0, 0]
    best_score = -10**9

    # Determine if a move lands in bounds / wall
    def legal(pos):
        x, y = pos
        if w is not None and (x < 0 or x >= w):
            return False
        if h is not None and (y < 0 or y >= h):
            return False
        if (x, y) in walls:
            return False
        return True

    # Pick a primary objective
    primary = None
    if resources:
        primary = min(resources, key=lambda p: manhattan(me, p))
    elif targets:
        primary = min(targets, key=lambda p: manhattan(me, p))

    for mv in moves:
        nxt = [me[0] + mv[0], me[1] + mv[1]]
        if not legal(nxt):
            continue

        score = 0

        # Prefer moving toward objective
        if primary is not None:
            d0 = manhattan(me, primary)
            d1 = manhattan(nxt, primary)
            score += (d0 - d1) * 10

        # Avoid threats
        if threats:
            nearest_threat = min(threats, key=lambda p: manhattan(nxt, p))
            dt = manhattan(nxt, nearest_threat)
            if dt == 0:
                score -= 100
            else:
                score += min(dt, 5) * 3

        # Mild preference for center / mobility if no objective
        if w is not None and h is not None:
            cx, cy = (w - 1) / 2.0, (h - 1) / 2.0
            score -= abs(nxt[0] - cx) * 0.05
            score -= abs(nxt[1] - cy) * 0.05

        # Avoid hugging walls if possible
        if w is not None and h is not None:
            edge_dist = min(nxt[0], nxt[1], w - 1 - nxt[0], h - 1 - nxt[1])
            score += edge_dist * 0.1

        # Small inertia toward diagonal movement when useful
        if mv != [0, 0]:
            score += 0.01

        if score > best_score:
            best_score = score
            best_move = mv

    if best_move == [0, 0] and primary is not None:
        step = sign_toward(me, primary)
        if legal([me[0] + step[0], me[1] + step[1]]):
            best_move = step

    return [int(best_move[0]), int(best_move[1])]

